    import semantic_kernel
    SEMANTIC_KERNEL_AVAILABLE = True
except ImportError:
    SEMANTIC_KERNEL_AVAILABLE = False
    print(f'  semantic_kernel non disponible - certaines fonctionnalites seront limitees')

class DoctorPlugin:
    """Plugin permettant au médecin de poser des questions complémentaires sur les symptômes."""
    @kernel_function(description="Pose des questions supplémentaires pour affiner le diagnostic.")
    def ask_followup_questions(self, symptom: Annotated[str, "Symptôme décrit par l'utilisateur"]) -> str:
        """Retourne une question en fonction du symptôme mentionné."""
        questions_map = {
            "fièvre": "Depuis combien de temps avez-vous de la fièvre ?",
            "maux de tête": "Avez-vous une sensibilité à la lumière ou au bruit ?",
            "douleur thoracique": "La douleur est-elle aiguë ou diffuse ?",
        }
        return questions_map.get(symptom.lower(), "Pouvez-vous donner plus de détails sur vos symptômes ?")

class MedicalAIPlugin:
    """Plugin qui analyse la gravité des symptômes."""
    @kernel_function(description="Vérifie la gravité d'un symptôme médical.")
    def check_symptom_severity(self, symptom: Annotated[str, "Symptôme décrit par l'utilisateur"]) -> str:
        """Retourne une évaluation de la gravité du symptôme."""
        severity_map = {
            "fièvre": "Modérée",
            "maux de tête": "Léger",
            "douleur thoracique": "Sévère",
            "perte de connaissance": "Critique"
        }
        return severity_map.get(symptom.lower(), "Inconnu - consultez un médecin.")

class PharmacistPlugin:
    """Plugin qui recommande des médicaments en fonction du diagnostic."""
    @kernel_function(description="Recommande un médicament adapté à un symptôme.")
    def recommend_medication(self, symptom: Annotated[str, "Symptôme décrit par l'utilisateur"]) -> str:
        """Retourne une suggestion de médicament (avec précautions)."""
        medication_map = {
            "fièvre": "Paracétamol (500mg, toutes les 6h, max 3 jours)",
            "maux de tête": "Ibuprofène (200mg, toutes les 8h, avec précaution si problème gastrique)",
            "douleur thoracique": "Aucun médicament recommandé - Consultez un médecin immédiatement",
        }
        return medication_map.get(symptom.lower(), "Aucun médicament recommandé - Consultez un pharmacien.")
print("Classe DoctorPlugin définie")
print("Classes DoctorPlugin, MedicalAIPlugin, PharmacistPlugin definies")

# Import guards - availability flags for external dependencies

try:
    from dotenv import load_dotenv
    DOTENV_AVAILABLE = True
except ImportError:
    DOTENV_AVAILABLE = False
    print(f'  dotenv non disponible - certaines fonctionnalites seront limitees')

try:
    import semantic_kernel
    SEMANTIC_KERNEL_AVAILABLE = True
except ImportError:
    SEMANTIC_KERNEL_AVAILABLE = False
    print(f'  semantic_kernel non disponible - certaines fonctionnalites seront limitees')

import pypdf
import re

pdf_path = shared_state.pdf_path
reader = pypdf.PdfReader(pdf_path)
pdf_text = chr(10).join(p.extract_text() or "" for p in reader.pages)
print(f"PDF généré avec succès: {pdf_path}")
print(f"Taille: {os.path.getsize(pdf_path)} octets")
print(f"Contenu extrait ({len(pdf_text)} caracteres):")
print(pdf_text)


def _norm(s):
    return re.sub(r"\s+", " ", s).strip().lower()


def _endswith(s, n_words=2):
    words = _norm(s).split()
    return " ".join(words[-n_words:]) if len(words) >= n_words else _norm(s)


def _check_ingredient(ing, pdf_text):
    """Vrai si l'ingredient (quantite + nom) est present dans le PDF.
    Test: chaine normalisee directe, OU variante sans virgule, OU split (nom + quantite)
    tous deux presents. Necessaire car le PDF peut mettre l'ingredient sur plusieurs lignes ou
    avec une virgule differente.
    """
    pdf_n = _norm(pdf_text)
    ing_n = _norm(ing)
    if ing_n in pdf_n:
        return True
    ing_no_comma = ing_n.replace(",", " ")
    if ing_no_comma in pdf_n:
        return True
    parts = [p.strip() for p in ing.split(",")]
    if len(parts) == 2 and _norm(parts[0]) in pdf_n and _norm(parts[1]) in pdf_n:
        return True
    return False


def _check_step(s, pdf_text, n_min_overlap=0.4):
    """Vrai si l'etape est presente dans le PDF avec un overlap de mots >= n_min_overlap
    ET les 2 derniers mots de l'etape sont dans le PDF (signe que la fin n'est pas
    tronquee). Le seul debut [:30] de V4 ne protegeait pas contre la troncature finale.
    """
    pdf_n = _norm(pdf_text)
    s_n = _norm(s)
    if s_n in pdf_n:
        return True
    s_words = s_n.split()
    if not s_words:
        return False
    p_words = set(pdf_n.split())
    overlap = sum(1 for w in s_words if w in p_words) / len(s_words)
    end_ok = _endswith(s, 2) in pdf_n
    return overlap >= n_min_overlap and end_ok


missing = []
if not shared_state.diet or _norm(shared_state.diet) not in _norm(pdf_text):
    missing.append(f"regime={shared_state.diet!r} absent du PDF")
if not shared_state.ingredients:
    missing.append("ingredients vides")
else:
    missing_ing = [i for i in shared_state.ingredients if not _check_ingredient(i, pdf_text)]
    if missing_ing:
        missing.append(
            f"{len(missing_ing)}/{len(shared_state.ingredients)} ingredients absents: {missing_ing[:3]}"
        )
if not shared_state.steps:
    missing.append("etapes vides")
else:
    missing_step = [s for s in shared_state.steps if not _check_step(s, pdf_text)]
    if missing_step:
        missing.append(
            f"{len(missing_step)}/{len(shared_state.steps)} etapes absentes: {missing_step[0][:50]}"
        )
if missing:
    raise RuntimeError(
        f"PDF incomplet -- {len(missing)} chaine(s) manquante(s) : "
        + " / ".join(missing)
    )
print("OK : PDF exporte la recette complete (regime + tous ingredients + toutes etapes).")

### Lecture du résultat : le duel verbal réel

L'exécution montre le protocole complet en action, tour par tour :

- **Sélection séquentielle des agents** : les logs `Selected agent at index 0/1` alternent Barbie puis l'Âne, conformément à `AgentGroupChat` et à sa stratégie de sélection par défaut ;
- **Contrainte respectée** : la contrainte tirée au sort est portée par les instructions système des deux agents, et leurs répliques la suivent ;
- **Le plugin d'image n'est branché que sur l'Âne** : seul `Ane_Shrek` déclenche `image_gen-generate_image`, conformément au câblage `kernel_ane.add_plugin(...)` ;
- **La terminaison fonctionne** : dès que l'historique atteint `MAX_TURNS`, `DebateTerminationStrategy` coupe la boucle.

La sortie est la **preuve de bout en bout** du montage : deux agents contraints, un plugin d'image branché sur l'instance ComfyUI de la série, une stratégie de terminaison — le tout orchestré par Semantic Kernel.

text_en:
### Reading the result: the real verbal duel

The execution shows the complete protocol in action, turn by turn:

- **Sequential agent selection**: the logs `Selected agent at index 0/1` alternate Barbie then the Donkey, in accordance with `AgentGroupChat` and its default selection strategy;
- **Constraint respected**: the randomly drawn constraint is carried by both agents' system instructions, and their replies follow it;
- **The image plugin is wired to the Donkey only**: only `Ane_Shrek` triggers `image_gen-generate_image`, in accordance with the `kernel_ane.add_plugin(...)` wiring;
- **Termination works**: as soon as the history reaches `MAX_TURNS`, `DebateTerminationStrategy` cuts the loop.

The output is the **end-to-end proof** of the setup: two constrained agents, an image plugin wired to the series' ComfyUI instance, a termination strategy — all orchestrated by Semantic Kernel.

text_fr:
### Exercice 1 — Une contrainte que le code peut vérifier

L'exemple guidé 1 ajoute des contraintes **déclaratives** : leur description est une phrase en français, et rien ne vérifie que le modèle l'a suivie. L'objectif est de rendre une contrainte **mesurable**.

**Objectif** :

1. définir une règle vérifiable mécaniquement — par exemple « la réplique contient au moins un mot de la liste `MOTS_ANES` » ;
2. écrire `taux_de_respect(repliques, regle)` qui reçoit les répliques d'un duel et **retourne la proportion** de répliques qui respectent la règle ;
3. l'appliquer au duel déjà présent dans le notebook (variable `repliques_du_duel`).

**Indices** :

- `# Étape 1` : une contrainte vérifiable = un nom, une description **et** une fonction `regle(texte) -> bool` ;
- `# Étape 2` : `result = None  # TODO étudiant`, puis le calcul réplique par réplique ;
- `# Indice` : `sum(1 for r in repliques if regle(str(r))) / len(repliques)`.

### Exercice 2 — Mettre l'Arbitre dans le duel

L'exemple guidé 2 crée l'agent `Arbitre`, mais le duel tourne toujours à deux : `AgentGroupChat(agents=[barbie, ane])` ne le convoque jamais. L'objectif est de le faire entrer dans la boucle **et** d'exploiter ce qu'il produit.

**Objectif** :

1. relancer un duel avec `agents=[barbie, ane, arbitre]` — pensez à relever `MAX_TURNS`, sinon l'Arbitre parle au mieux une fois ;
2. collecter les répliques de ce nouveau duel ;
3. écrire `notes_arbitre(repliques)` qui retourne la liste des notes sur 10 que l'Arbitre a attribuées, extraites du texte (par exemple avec `re.compile(r"(\d+(?:[.,]\d+)?)\s*/\s*10")`) ;
4. afficher le nombre de notes et leur moyenne.

**Indices** :

- `# Étape 1` : `chat = AgentGroupChat(agents=[barbie, ane, arbitre], termination_strategy=DebateTerminationStrategy())` ;
- `# Étape 2` : parcourir les répliques dont `msg.name == "Arbitre"` ;
- `# Indice` : `float(m.group(1).replace(",", "."))` pour convertir la note trouvée.

### Exercice 3 — Une détection de capitulation qui ne se trompe pas de cible

L'exemple guidé 3 détecte la capitulation par **sous-chaîne** dans le dernier message. Deux façons de se tromper, toutes deux mesurables : « je n'abandonnerai jamais » (négation) et « tu vas abandonner, l'Âne » (parler de l'autre) déclenchent l'arrêt alors que personne ne cède.

**Objectif** :

1. écrire `capitule(phrase)` qui ne renvoie `True` que pour une capitulation **du locuteur** — à la première personne et non niée ;
2. la tester sur une liste de phrases pièges, **sans appeler le modèle** : c'est un test unitaire, il doit être déterministe ;
3. (bonus) réimplémenter `SurrenderTerminationStrategy` sur le point d'accroche canonique `should_agent_terminate` et vérifier que le duel se comporte pareil.

**Indices** :

- `# Étape 1` : `re.compile(r"\b(j'abandonne|je me rends|je capitule)\b")` — et traiter la négation (`n'`, `ne ... jamais`, `pas`) ;
- `# Étape 2` : tester au minimum « Je n'abandonnerai jamais ! », « Tu vas abandonner, l'Âne ! », « J'abandonne, tu gagnes. » ;
- `# Indice` : retourner un `dict` phrase -> booléen attendu/observé, et compter les écarts.
